    answersHidden: document.getElementById("lc-answers").classList.contains("hidden"),
  };
})()

(() => {
  document.querySelector('#lc-answers [data-chip="1"]').click(); // wrong
  const out = document.getElementById("lc-output");
  const afterWrong = { marvinIcons: out.querySelectorAll("img.marvin-icon").length, tail: out.textContent.trim().slice(-40) };
  document.querySelector('#lc-answers [data-chip="0"]').click(); // correct
  const afterCorrect = { marvinIcons: out.querySelectorAll("img.marvin-icon").length, tail: out.textContent.trim().slice(-60) };
  return { afterWrong, afterCorrect };
})()

(() => {
  const out = document.getElementById("lc-output");
  return {
    question: document.getElementById("lc-question")?.textContent,
    outputHidden: out.classList.contains("hidden"),
    outputText: out.textContent.trim(),
